"use client";

import { Canvas } from "@react-three/fiber";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useRef } from "react";
import SystemCore from "./SystemCore";

gsap.registerPlugin(ScrollTrigger);

export default function Hero() {
    const sectionRef = useRef<HTMLElement>(null);
    const copyRef = useRef<HTMLDivElement>(null);
    const stageRef = useRef<HTMLDivElement>(null);

    const scrollProgress = useRef(0);

    useGSAP(
        () => {
            if (!sectionRef.current) return;

            const ctx = gsap.context(() => {
                gsap.fromTo(
                    ".hero-eyebrow",
                    {
                        opacity: 0,
                        y: 20,
                    },
                    {
                        opacity: 1,
                        y: 0,
                        duration: 1,
                        ease: "power3.out",
                    }
                );

                gsap.fromTo(
                    ".hero-title-line",
                    {
                        opacity: 0,
                        y: 80,
                    },
                    {
                        opacity: 1,
                        y: 0,
                        duration: 1.1,
                        stagger: 0.12,
                        delay: 0.1,
                        ease: "power4.out",
                    }
                );

                gsap.fromTo(
                    ".hero-description",
                    {
                        opacity: 0,
                        y: 20,
                    },
                    {
                        opacity: 1,
                        y: 0,
                        duration: 0.8,
                        delay: 0.55,
                        ease: "power3.out",
                    }
                );

                gsap.fromTo(
                    ".hero-action",
                    {
                        opacity: 0,
                        y: 15,
                    },
                    {
                        opacity: 1,
                        y: 0,
                        duration: 0.8,
                        delay: 0.7,
                        ease: "power3.out",
                    }
                );

                gsap.fromTo(
                    stageRef.current,
                    {
                        opacity: 0,
                        scale: 0.75,
                        x: 100,
                    },
                    {
                        opacity: 1,
                        scale: 1,
                        x: 0,
                        duration: 1.4,
                        delay: 0.2,
                        ease: "expo.out",
                    }
                );

                gsap.timeline({
                    scrollTrigger: {
                        trigger: sectionRef.current,
                        start: "top top",
                        end: "+=1800",
                        scrub: 1.2,
                        pin: true,
                        onUpdate: (self) => {
                            scrollProgress.current = self.progress;
                        },
                    },
                })
                    .to(copyRef.current, {
                        x: -120,
                        opacity: 0.2,
                        duration: 0.35,
                        ease: "power2.inOut",
                    })
                    .to(
                        stageRef.current,
                        {
                            x: 100,
                            scale: 1.2,
                            duration: 0.45,
                            ease: "power2.inOut",
                        },
                        "<"
                    )
                    .to(
                        ".hero-title",
                        {
                            letterSpacing: "0.04em",
                            duration: 0.25,
                        },
                        "<"
                    )
                    .to(
                        stageRef.current,
                        {
                            x: 0,
                            scale: 1.45,
                            duration: 0.45,
                            ease: "power3.inOut",
                        }
                    )
                    .to(
                        ".hero-system-label",
                        {
                            opacity: 1,
                            y: 0,
                            duration: 0.25,
                        },
                        "<"
                    );
            }, sectionRef);

            return () => ctx.revert();
        },
        { scope: sectionRef }
    );

    return (
        <section ref={sectionRef} className="hero">
            <div className="hero-grid" />

            <div ref={copyRef} className="hero-copy">
                <p className="hero-eyebrow">
                    PRITAM / SYSTEMS / 2026
                </p>

                <h1 className="hero-title">
                    <span className="hero-title-line">SOFTWARE</span>
                    <span className="hero-title-line">ENGINEER</span>
                </h1>

                <p className="hero-description">
                    I build intelligent backend systems,
                    distributed architectures and
                    AI-powered products.
                </p>

                <a href="#projects" className="hero-action">
                    EXPLORE WORK <span>↗</span>
                </a>
            </div>

            <div ref={stageRef} className="hero-stage">
                <Canvas
                    camera={{
                        position: [0, 0, 7],
                        fov: 42,
                    }}
                    dpr={[1, 1.75]}
                    gl={{
                        antialias: true,
                        alpha: true,
                    }}
                >
                    <SystemCore scrollProgress={scrollProgress} />
                </Canvas>

                <div className="hero-system-label">
                    <span>SYSTEM / 01</span>
                    <span>ACTIVE</span>
                </div>
            </div>

            <div className="hero-footer">
                <span>BENGALURU / INDIA</span>
                <span>SCROLL TO EXPLORE ↓</span>
                <span>AI / BACKEND / SYSTEMS</span>
            </div>
        </section>
    );
}